'use strict';
let evaluationModel=null,evaluationGroups=[],evaluationUnassigned=[],evaluationPage=0,evaluationSelectedGroup=null,evaluationRun=null;
const evaluationColours={short:'#277a58',medium:'#31848b',long:'#bb802c',far:'#a34d42',unknown:'#7c8180'};
const evaluationPoints=L.layerGroup(),evaluationCircles=L.layerGroup(),evaluationRoute=L.layerGroup();
map.createPane('evaluationPane');map.getPane('evaluationPane').style.zIndex=440;
const evaluationRenderer=L.canvas({pane:'evaluationPane',padding:.5});
const evaluationDefaults=state.evaluationSettings||{objective:'distance',paved:40,unpaved:25,maxGap:250,minimum:5,radius:500};
for(const [id,key]of[['evalobjective','objective'],['evalpaved','paved'],['evalunpaved','unpaved'],['evalgap','maxGap'],['evalminimum','minimum'],['evalradius','radius']])$(id).value=evaluationDefaults[key];
function evaluationColour(r){return r.status!=='routed'?evaluationColours.unknown:r.time_min<=5?evaluationColours.short:r.time_min<=10?evaluationColours.medium:r.time_min<=20?evaluationColours.long:evaluationColours.far}
function evaluationReason(r){return({routed:'Routed road leg',access_gap:'Building-to-road gap exceeds limit',no_connection:'Road component cannot reach hydrant',hydrant_gap:'Hydrant-to-road gap exceeds limit'})[r.status]||r.status}
function readEvaluationSettings(){return{objective:$('evalobjective').value,paved:Number($('evalpaved').value),unpaved:Number($('evalunpaved').value),maxGap:Number($('evalgap').value),minimum:Number($('evalminimum').value),radius:Number($('evalradius').value)}}
function routeSettingsValid(){return['evalpaved','evalunpaved','evalgap'].every(id=>$(id).reportValidity())}
function runBuildingEvaluation(clearGroups=true){if(!routeSettingsValid())return false;if(!buildingFeatures.length||!ornFeatures.length){$('evalstatus').textContent='Waiting for buildings and roads to load.';return false}const target=state.water.find(w=>w.id==='resort'&&w.coord);if(!target){$('hydrantgapnote').textContent='The resort hydrant record is missing its pin. Restore it before running this analysis.';return false}let settings=readEvaluationSettings(),routes=[...scenarioRoads(true,settings),...state.roads.filter(r=>!r.demo&&r.status!=='Closed'&&r.speed>0)],points=buildingFeatures.map(f=>({id:f.id||f.properties.id,coord:[f.properties.centre[1],f.properties.centre[0]]}));evaluationModel=buildHydrantAnalysis(routes,points,target.coord,settings,distance);evaluationRun={settings:{...settings},target:{id:target.id,name:target.name,coord:[...target.coord]},run_at:new Date().toISOString()};state.evaluationSettings=settings;save();evaluationPage=0;const routed=evaluationModel.rows.filter(r=>r.status==='routed'),unresolved=evaluationModel.rows.length-routed.length,gap=evaluationModel.targetSnap?.gap;
$('evalstats').innerHTML=`<div><strong>${routed.length}</strong><span>routed road legs</span></div><div><strong>${unresolved}</strong><span>unresolved</span></div><div><strong>${gap==null?'—':Math.round(gap)+' m'}</strong><span>hydrant road gap</span></div>`;
$('hydrantgapnote').textContent=gap==null?'No eligible road geometry.':gap>settings.maxGap?`Hydrant gap ${Math.round(gap)} m exceeds the ${settings.maxGap} m limit. No routes can be assigned.`:`Hydrant access gap: ${Math.round(gap)} m. This access leg is not in the road data and is excluded from every route distance and driving time. Add verified access geometry to improve the analysis.`;
$('evalstatus').textContent=`${evaluationModel.rows.length} structures assessed · ${settings.objective==='distance'?'shortest road distance':'fastest estimated drive'} · paved ${settings.paved} / unpaved ${settings.unpaved} km/h assumptions · max gap ${settings.maxGap} m. Results use these last-run settings.`;
if(clearGroups){evaluationGroups=[];evaluationUnassigned=[];evaluationSelectedGroup=null;$('evalclusterlist').innerHTML='<p class="hint">Select Evaluate clusters to group the current building extract.</p>';$('evalclustercount').textContent='';$('evalclusterselected').innerHTML=''}
$('evalbuildingselected').innerHTML='';evaluationRoute.clearLayers();renderEvaluationBuildings();drawEvaluationLayers();return true}
function evaluationGroupStats(group){const members=new Set(group.members),rows=evaluationModel.rows.filter(r=>members.has(r.building_id)),routed=rows.filter(r=>r.status==='routed'),mean=key=>routed.length?routed.reduce((s,r)=>s+r[key],0)/routed.length:null,max=key=>routed.length?Math.max(...routed.map(r=>r[key])):null;return{rows,routed:routed.length,unresolved:rows.length-routed.length,meanKm:mean('distance_km'),maxKm:max('distance_km'),meanMin:mean('time_min'),maxMin:max('time_min')}}
function evaluateBuildingClusters(){if(!$('evaluationform').reportValidity()||!runBuildingEvaluation(false))return;const s=evaluationRun.settings,points=evaluationModel.rows.map(r=>({id:r.building_id,coord:[r.lat,r.lng]})),result=fixedRadiusClusters(points,s.radius/1000,s.minimum,distance);evaluationGroups=result.groups;evaluationUnassigned=result.unassigned;evaluationSelectedGroup=null;$('evalclusterselected').innerHTML='';$('evalclustercount').textContent=`${result.groups.length} groups`;$('evalclusterlist').innerHTML=`<p class="hint">${points.length-result.unassigned.length} of ${points.length} structures assigned · ${result.unassigned.length} unassigned · ${s.radius} m radius / minimum ${s.minimum}. Groups include unresolved buildings.</p>`;for(const g of evaluationGroups){const stats=evaluationGroupStats(g),b=document.createElement('button');b.className='item';b.innerHTML=`<span class="badge teal">${g.members.length} STRUCTURES</span><strong>${g.id} · fixed-radius group</strong><small>${stats.routed} routed / ${stats.unresolved} unresolved<br>${stats.meanMin==null?'No estimated road journeys':`Mean ${stats.meanKm.toFixed(1)} km · ${stats.meanMin.toFixed(1)} min; longest ${stats.maxMin.toFixed(1)} min`}</small>`;b.onclick=()=>selectEvaluationCluster(g.id);$('evalclusterlist').appendChild(b)}if(!evaluationGroups.length)$('evalclusterlist').innerHTML+='<p class="hint empty">No groups meet those settings. Reduce the minimum count or increase the radius.</p>';drawEvaluationLayers();if(evaluationGroups.length)map.fitBounds(L.latLngBounds(evaluationGroups.map(g=>g.coord)),{padding:[60,60],maxZoom:12})}
function drawEvaluationLayers(){evaluationPoints.clearLayers();evaluationCircles.clearLayers();if(activeTab!=='evaluate'){map.removeLayer(evaluationPoints);map.removeLayer(evaluationCircles);map.removeLayer(evaluationRoute);return}evaluationPoints.addTo(map);evaluationCircles.addTo(map);evaluationRoute.addTo(map);if(evaluationModel&&$('evalshowbuildings').checked)for(const r of evaluationModel.rows){L.circleMarker([r.lat,r.lng],{radius:4,color:'#fff',weight:.7,fillColor:evaluationColour(r),fillOpacity:.9,pane:'evaluationPane',renderer:evaluationRenderer}).addTo(evaluationPoints).bindTooltip(`${r.label} · ${r.status==='routed'?r.distance_km.toFixed(2)+' km / '+r.time_min.toFixed(1)+' min':evaluationReason(r)}`).on('click',()=>selectEvaluationBuilding(r.building_id))}for(const g of evaluationGroups){let c=L.circle(g.coord,{radius:g.radiusKm*1000,color:g.id===evaluationSelectedGroup?'#a34d42':'#725991',weight:g.id===evaluationSelectedGroup?3:2,fillOpacity:.06,pane:'evaluationPane'}).addTo(evaluationCircles);c.bindTooltip(`${g.id} · ${g.members.length} detected structures`).on('click',()=>selectEvaluationCluster(g.id));L.marker(g.coord,{icon:L.divIcon({className:'',html:`<span class="evaluation-group-pin">${g.id}<small>${g.members.length}</small></span>`,iconSize:[38,34],iconAnchor:[19,17]}),title:g.id+' · '+g.members.length+' structures'}).addTo(evaluationCircles).on('click',()=>selectEvaluationCluster(g.id))}}
function selectEvaluationCluster(id){const g=evaluationGroups.find(g=>g.id===id);if(!g)return;evaluationSelectedGroup=id;const s=evaluationGroupStats(g);$('evalclusterselected').innerHTML=`<div class="source-card"><span class="badge purple">${g.id} · ${g.members.length} STRUCTURES</span><h3>Candidate-area evidence</h3><p>${g.radiusKm*1000} m radius · centre ${g.coord.map(n=>n.toFixed(5)).join(', ')}<br>${s.routed} routed, ${s.unresolved} unresolved.</p><p>${s.meanKm==null?'No usable road-distance estimates.':`Mean road leg: ${s.meanKm.toFixed(2)} km / ${s.meanMin.toFixed(1)} min<br>Maximum: ${s.maxKm.toFixed(2)} km / ${s.maxMin.toFixed(1)} min`}</p><p class="hint">Structure count is not a count of homes. This circle identifies an area to review, not a suitable tank installation site.</p><button id="evalcandidate" class="wide">Review as storage candidate</button></div>`;$('evalcandidate').onclick=()=>planEdit('candidate',null,g.coord,{name:g.id+' — storage study area',notes:`Fixed-radius evaluation: ${g.members.length} detected structures within ${g.radiusKm*1000} m. ${s.routed} routed / ${s.unresolved} unresolved. Residential use, road access and installation suitability are unverified. ${s.meanMin==null?'':`Mean modelled road leg ${s.meanKm.toFixed(2)} km / ${s.meanMin.toFixed(1)} min. Access legs excluded.`}`});evaluationRoute.clearLayers();drawEvaluationLayers();map.fitBounds(L.latLng(g.coord).toBounds(g.radiusKm*2000),{padding:[60,60],maxZoom:15});$('evalclusterselected').scrollIntoView({block:'nearest'})}
function selectEvaluationBuilding(id){if(!evaluationModel)return;const r=evaluationModel.rows.find(r=>r.building_id===id);if(!r)return;evaluationRoute.clearLayers();const p=[r.lat,r.lng],target=evaluationRun.target.coord;$('evalbuildingselected').innerHTML=`<div class="source-card"><span class="badge teal">${esc(r.label)} · ${esc(evaluationReason(r))}</span><h3>${r.status==='routed'?r.distance_km.toFixed(2)+' km · '+r.time_min.toFixed(1)+' min':'No road journey assigned'}</h3><p class="hint">Footprint ID: ${esc(r.building_id)}<br>Centre: ${r.lat.toFixed(6)}, ${r.lng.toFixed(6)}<br>Building road gap: ${r.building_access_m==null?'unknown':Math.round(r.building_access_m)+' m'}<br>Hydrant road gap: ${r.hydrant_access_m==null?'unknown':Math.round(r.hydrant_access_m)+' m'}<br>Road leg only; access gaps excluded.<br>Blue line: road route. Grey dashes: unmodelled access links.</p></div>`;let coords=[p];if(r.status==='routed'){const roadPath=evaluationModel.pathFor(r);L.polyline(roadPath,{color:'#216b96',weight:6,opacity:.95,pane:'evaluationPane',interactive:false}).addTo(evaluationRoute);L.polyline([p,r.snap.point],{color:'#5f6663',weight:2,dashArray:'5 5',pane:'evaluationPane',interactive:false}).addTo(evaluationRoute);L.polyline([evaluationModel.targetSnap.point,target],{color:'#5f6663',weight:2,dashArray:'5 5',pane:'evaluationPane',interactive:false}).addTo(evaluationRoute);coords=[p,...roadPath,target]}L.circleMarker(p,{radius:8,color:'#216b96',fillOpacity:0,pane:'evaluationPane'}).addTo(evaluationRoute);map.fitBounds(L.latLngBounds(coords),{padding:[70,70],maxZoom:16});$('evalbuildingselected').scrollIntoView({block:'nearest'})}
function evaluationBuildingClick(f){if(activeTab!=='evaluate'||!evaluationModel)return false;selectEvaluationBuilding(f.id||f.properties.id);return true}
function renderEvaluationBuildings(){if(!evaluationModel)return;let q=$('evalsearch').value.trim().toLowerCase(),sort=$('evalsort').value,rows=evaluationModel.rows.filter(r=>[r.label,r.building_id,evaluationReason(r)].join(' ').toLowerCase().includes(q));rows.sort((a,b)=>sort==='id'?a.label.localeCompare(b.label):sort==='unresolved'?(Number(a.status==='routed')-Number(b.status==='routed')||a.label.localeCompare(b.label)):(b[sort==='time'?'time_min':'distance_km']??-1)-(a[sort==='time'?'time_min':'distance_km']??-1)||a.label.localeCompare(b.label));let pages=Math.max(1,Math.ceil(rows.length/20));evaluationPage=Math.max(0,Math.min(evaluationPage,pages-1));$('evalbuildinglist').innerHTML='';for(const r of rows.slice(evaluationPage*20,evaluationPage*20+20)){let b=document.createElement('button');b.className='evaluation-building-row';b.innerHTML=`<span><i style="background:${evaluationColour(r)}"></i>${esc(r.label)}</span><span>${r.status==='routed'?r.distance_km.toFixed(2)+' km':'—'}</span><span>${r.status==='routed'?r.time_min.toFixed(1)+' min':'unresolved'}</span>`;b.title=evaluationReason(r)+' · '+r.building_id;b.onclick=()=>selectEvaluationBuilding(r.building_id);$('evalbuildinglist').appendChild(b)}$('evalpage').textContent=`${rows.length?evaluationPage*20+1:0}–${Math.min(rows.length,(evaluationPage+1)*20)} / ${rows.length}`;$('evalprev').disabled=evaluationPage===0;$('evalnext').disabled=evaluationPage>=pages-1}
function downloadEvaluationFile(name,body,mime){const u=URL.createObjectURL(new Blob([body],{type:mime})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csvEvaluation(rows){return rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n')}
function publicEvaluationRows(){return evaluationModel.rows.map(({choice,snap,...r})=>r)}
$('exportbuildingcsv').onclick=()=>{if(!evaluationModel)return;const keys=['label','building_id','lat','lng','status','distance_km','time_min','building_access_m','hydrant_access_m'];let rows=[...evaluationModel.rows].sort((a,b)=>a.label.localeCompare(b.label));downloadEvaluationFile('searchmont-building-hydrant-routes.csv',csvEvaluation([[...keys,'route_objective','assumed_paved_kmh','assumed_unpaved_kmh','max_access_gap_m','road_legs_only'],...rows.map(r=>[...keys.map(k=>r[k]),evaluationRun.settings.objective,evaluationRun.settings.paved,evaluationRun.settings.unpaved,evaluationRun.settings.maxGap,true])]),'text/csv')};
$('exportclustercsv').onclick=()=>{if(!evaluationModel||!evaluationGroups.length){$('evalstatus').textContent='Evaluate clusters before exporting cluster results.';return}downloadEvaluationFile('searchmont-building-clusters.csv',csvEvaluation([['cluster','lat','lng','radius_m','structures','routed','unresolved','mean_road_km','max_road_km','mean_driving_min','max_driving_min','building_ids'],...evaluationGroups.map(g=>{const s=evaluationGroupStats(g);return[g.id,...g.coord,g.radiusKm*1000,g.members.length,s.routed,s.unresolved,s.meanKm,s.maxKm,s.meanMin,s.maxMin,g.members.join('|')]})]),'text/csv')};
$('exportevaluation').onclick=()=>{if(!evaluationModel)return;downloadEvaluationFile('searchmont-building-evaluation.json',JSON.stringify({description:'Road legs only; access gaps, filling and turnaround excluded. Structure use and road access unverified.',...evaluationRun,building_source:'Microsoft Canadian Building Footprints — ODbL',road_source:'Ontario Road Network Composite — Open Government Licence – Ontario',rows:publicEvaluationRows(),groups:evaluationGroups,unassigned:evaluationUnassigned},null,2),'application/json')};
$('runroutes').onclick=()=>runBuildingEvaluation();$('evaluationform').onsubmit=e=>{e.preventDefault();evaluateBuildingClusters()};$('evalshowbuildings').onchange=drawEvaluationLayers;for(const id of['evalsearch','evalsort'])$(id).oninput=()=>{evaluationPage=0;renderEvaluationBuildings()};$('evalprev').onclick=()=>{evaluationPage--;renderEvaluationBuildings()};$('evalnext').onclick=()=>{evaluationPage++;renderEvaluationBuildings()};for(const id of['evalobjective','evalpaved','evalunpaved','evalgap','evalminimum','evalradius'])$(id).addEventListener('input',()=>{if(evaluationModel)$('evalstatus').textContent='Settings changed. Displayed results use the previous run; run routes or Evaluate clusters to apply changes.'});
for(const b of document.querySelectorAll('nav button')){const old=b.onclick;b.onclick=()=>{old();drawEvaluationLayers()}}
function initialBuildingEvaluation(){if(!evaluationModel&&buildingFeatures.length&&ornFeatures.length)runBuildingEvaluation()}
window.addEventListener('geodata-ready',initialBuildingEvaluation);initialBuildingEvaluation();

window.addEventListener('network-assumptions-changed',()=>{if(evaluationModel)$('evalstatus').textContent='Road assumptions changed. Run routes or Evaluate clusters to update the displayed results.'});
const beforeEvaluationRender=render;render=function(){beforeEvaluationRender();if(evaluationModel)$('evalstatus').textContent='Inventory changed. Run routes or Evaluate clusters to update the displayed results.'};
